namespace {

double Scale(double value, double max_abs) {
  // 非有限值兜底：NaN 属于无效指令直接归零；±Inf 视为超限走下方钳位
  if (std::isnan(value)) return 0.0;
  if (std::abs(value) <= max_abs) return value;
  return (value > 0 ? max_abs : -max_abs);
}

}  // namespace

